package v1

import (
	metav1 "k8s.io/apimachinery/pkg/apis/meta/v1"
	"k8s.io/apimachinery/pkg/runtime"
	"sigs.k8s.io/controller-runtime/pkg/scheme"
)

// TenantAppSpec is the DESIRED state of a deployed tenant app. The worker fills
// this in after a successful build; the operator reconciles reality to match it.
//
// The // +kubebuilder markers are how the CRD's OpenAPI schema is generated by
// controller-gen. We also ship a hand-written CRD in deploy/crd that matches
// this struct exactly.
type TenantAppSpec struct {
	// ImageURI is the fully-qualified container image to run (registry + tag).
	ImageURI string `json:"imageUri"`
	// Subdomain is the app's DNS label; the Ingress host is <subdomain>.<domain>.
	Subdomain string `json:"subdomain"`
	// Replicas is the desired number of pods.
	// +kubebuilder:default=1
	Replicas int32 `json:"replicas"`
	// CPULimit is the per-pod CPU limit (Kubernetes quantity, e.g. "250m").
	CPULimit string `json:"cpuLimit"`
	// MemoryLimit is the per-pod memory limit (e.g. "256Mi").
	MemoryLimit string `json:"memoryLimit"`
	// ContainerPort is the port the app listens on inside the container.
	ContainerPort int32 `json:"containerPort"`
}

// TenantAppStatus is the OBSERVED state, written by the operator. Separating
// spec (desired, user-owned) from status (observed, controller-owned) is a core
// Kubernetes API convention.
type TenantAppStatus struct {
	// Phase is a coarse lifecycle summary: Pending, Provisioning, Ready, Failed.
	Phase string `json:"phase,omitempty"`
	// Message is a human-readable detail for the current phase.
	Message string `json:"message,omitempty"`
	// URL is the public URL once the Ingress is configured.
	URL string `json:"url,omitempty"`
	// ObservedGeneration is the spec generation the status reflects, so clients
	// can tell whether the operator has caught up with the latest spec.
	ObservedGeneration int64 `json:"observedGeneration,omitempty"`
}

// Phase constants for TenantAppStatus.Phase.
const (
	PhasePending      = "Pending"
	PhaseProvisioning = "Provisioning"
	PhaseReady        = "Ready"
	PhaseFailed       = "Failed"
)

// +kubebuilder:object:root=true
// +kubebuilder:subresource:status

// TenantApp is the Schema for the tenantapps API.
type TenantApp struct {
	metav1.TypeMeta   `json:",inline"`
	metav1.ObjectMeta `json:"metadata,omitempty"`

	Spec   TenantAppSpec   `json:"spec,omitempty"`
	Status TenantAppStatus `json:"status,omitempty"`
}

// +kubebuilder:object:root=true

// TenantAppList contains a list of TenantApp.
type TenantAppList struct {
	metav1.TypeMeta `json:",inline"`
	metav1.ListMeta `json:"metadata,omitempty"`
	Items           []TenantApp `json:"items"`
}

// SchemeBuilder registers our types with a runtime.Scheme. controller-runtime
// uses the scheme to map Go types <-> GroupVersionKinds.
var (
	SchemeBuilder = &scheme.Builder{GroupVersion: GroupVersion}
	// AddToScheme adds the types in this group-version to a scheme.
	AddToScheme = SchemeBuilder.AddToScheme
)

func init() {
	SchemeBuilder.Register(&TenantApp{}, &TenantAppList{})
}

// ---- DeepCopy methods ----------------------------------------------------
//
// Every type stored via the Kubernetes API must implement runtime.Object, which
// requires DeepCopyObject. These are normally generated by controller-gen into a
// zz_generated.deepcopy.go file; we hand-write them here because the types are
// simple (only value fields), which keeps the build free of a code-gen step.

// DeepCopyInto copies the receiver into out.
func (in *TenantApp) DeepCopyInto(out *TenantApp) {
	*out = *in
	out.TypeMeta = in.TypeMeta
	in.ObjectMeta.DeepCopyInto(&out.ObjectMeta)
	out.Spec = in.Spec     // Spec has only value fields
	out.Status = in.Status // Status has only value fields
}

// DeepCopy returns a deep copy of the receiver.
func (in *TenantApp) DeepCopy() *TenantApp {
	if in == nil {
		return nil
	}
	out := new(TenantApp)
	in.DeepCopyInto(out)
	return out
}

// DeepCopyObject satisfies runtime.Object.
func (in *TenantApp) DeepCopyObject() runtime.Object {
	if c := in.DeepCopy(); c != nil {
		return c
	}
	return nil
}

// DeepCopyInto copies the list into out.
func (in *TenantAppList) DeepCopyInto(out *TenantAppList) {
	*out = *in
	out.TypeMeta = in.TypeMeta
	in.ListMeta.DeepCopyInto(&out.ListMeta)
	if in.Items != nil {
		out.Items = make([]TenantApp, len(in.Items))
		for i := range in.Items {
			in.Items[i].DeepCopyInto(&out.Items[i])
		}
	}
}

// DeepCopy returns a deep copy of the list.
func (in *TenantAppList) DeepCopy() *TenantAppList {
	if in == nil {
		return nil
	}
	out := new(TenantAppList)
	in.DeepCopyInto(out)
	return out
}

// DeepCopyObject satisfies runtime.Object.
func (in *TenantAppList) DeepCopyObject() runtime.Object {
	if c := in.DeepCopy(); c != nil {
		return c
	}
	return nil
}
